config.script:
ticket_id = (path or {}).get("ticket_id")
if not ticket_id:
    result = {"code": 400, "message": "缺少车票ID", "data": None}
else:
    ticket = entity_find_one("ticket", filters={"id": ticket_id})
    if not ticket:
        ticket = entity_find_one("ticket", filters={"ticket_id": ticket_id})
    if not ticket:
        ticket = entity_find_one("ticket", filters={"ticket_number": ticket_id})
    if not ticket:
        result = {"code": 404, "message": "车票不存在", "data": None}
    else:
        price = (body or {}).get("price")
        if price is None:
            price = ticket.get("price") or 0
        try:
            price = float(price)
        except (TypeError, ValueError):
            price = 0
        rate = (body or {}).get("refund_rate")
        if rate is None:
            rate = 0.1 if price <= 100 else (0.15 if price <= 300 else 0.2)
        else:
            try:
                rate = float(rate)
            except (TypeError, ValueError):
                rate = 0
        refund_fee = round(price * rate, 2)
        refund_amount = round(price - refund_fee, 2)
        data = {
            "original_amount": price,
            "refund_fee": refund_fee,
            "refund_amount": refund_amount,
            "fee_rate": rate,
            "ticket_id": ticket.get("ticket_id") or ticket.get("id"),
        }
        result = {"code": 200, "message": "计算成功", "data": data}
